using HarmonyLib;
using System.Linq;
using System.Reflection;
using TaleWorlds.GauntletUI.BaseTypes;

namespace Alliance.Client.Patch.HarmonyPatch
{
    public static class Patch_MPChatLog
    {
        private static readonly Harmony Harmony = new(SubModule.ModuleId + nameof(Patch_MPChatLog));
        private static bool _patched;

        public static bool Patch()
        {
            if (_patched)
                return false;
            _patched = true;

            var targetType = AccessTools.TypeByName(
                "TaleWorlds.MountAndBlade.GauntletUI.AutoGenerated0.MPChatLog__TaleWorlds_MountAndBlade_ViewModelCollection_Multiplayer_MPChatVM"
            );

            if (targetType == null)
                return false;

            var method = targetType.GetMethod("SetAttributes",
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);

            var postfix = typeof(Patch_MPChatLog).GetMethod(nameof(Postfix),
                BindingFlags.Static | BindingFlags.NonPublic);

            Harmony.Patch(method, postfix: new HarmonyMethod(postfix));

            return true;
        }

        private static void Postfix(object __instance)
        {
            if (__instance is not Widget root)
                return;

            var chatLog = root.Children.FirstOrDefault();
            if (chatLog == null)
                return;

            // 🔧 Increase total chat height
            chatLog.SuggestedHeight = 800f;
            chatLog.SuggestedWidth += 160f;
        }
    }
}